const run = Date.now().toString();
for(const key of Object.keys(pm.environment.toObject())) {
 if ((key.endsWith("Id") || key.startsWith("registrationCookie") || key.startsWith("paymentUrl") || key === "reminderCreatedAt" || key === "mergeAssigned") && key !== "cleanupCampaignId") pm.environment.unset(key);
}
pm.environment.set("runId", run);
pm.environment.set("entityIdKey", "id");
const today = new Date();
pm.environment.set("startDate", today.toISOString().slice(0,10));
pm.environment.set("endDate", new Date(today.getTime()+30*86400000).toISOString().slice(0,10));
const email = pm.environment.get("testEmail") || "";
const at = email.lastIndexOf("@");
if(at < 1 || !pm.environment.get("adminPassword") || !/^05\d{8}$/.test(pm.environment.get("testPhone") || "")) {
 pm.execution.skipRequest(); throw new Error("Select ONS Local environment and fill adminPassword, testEmail (Gmail/plus-alias mailbox), and testPhone (05xxxxxxxx).");
}
const local = email.slice(0,at).split("+")[0], domain=email.slice(at+1);
for(const actor of ["campaignA","campaignB","campaignProbe","supervisorA","supervisorB","employeeA","employeeB","employeeSpare","fieldA","fieldB","fieldSpare","supervisorSpare"]) {
 pm.environment.set(actor+"Email", local+"+ons-"+actor.toLowerCase()+"-"+run+"@"+domain);
 if(!actor.startsWith("campaign")) pm.environment.set(actor+"Password", pm.environment.get("testPassword"));
}
for(const [i,key] of ["cardIdA","cardIdB","cardIdSpare"].entries()) pm.environment.set(key, String(10000000+Number(run.slice(-7))+i));
for(const suffix of ["A","B","Spare"]) {
 pm.environment.set("visa"+suffix, "ONS-VISA-"+suffix+"-"+run);
 pm.environment.set("cardNumber"+suffix, "ONS-CARD-"+suffix+"-"+run);
}

