const paths=[];
function walk(x,p){if(!x || typeof x!=="object") return;for(const [k,v] of Object.entries(x)){if(k.toLowerCase()==="password" && v!==null && v!=="") paths.push(p+"."+k);else walk(v,p+"."+k);}}
walk(pm.response.json(),"response");
pm.test("No password values serialized",()=>pm.expect(paths,"Password field locations only; values are intentionally not logged").to.be.empty);

